use std::collections::VecDeque;
use std::io::{self, Read, Write};

const UNDO_LIMIT: usize = 5;

/// An edit knows how to apply itself and how to revert itself.
enum Edit {
    Insert { idx: usize, text: String },
    Delete { idx: usize, removed: String },
    Replace { idx: usize, text: String, old: String },
    Swap { a: usize, b: usize },
}

impl Edit {
    fn apply(&mut self, buf: &mut Vec<String>) {
        match self {
            Edit::Insert { idx, text } => buf.insert(*idx, text.clone()),
            Edit::Delete { idx, removed } => *removed = buf.remove(*idx),
            Edit::Replace { idx, text, old } => {
                *old = std::mem::replace(&mut buf[*idx], text.clone());
            }
            Edit::Swap { a, b } => buf.swap(*a, *b),
        }
    }

    fn revert(&self, buf: &mut Vec<String>) {
        match self {
            Edit::Insert { idx, .. } => {
                buf.remove(*idx);
            }
            Edit::Delete { idx, removed } => buf.insert(*idx, removed.clone()),
            Edit::Replace { idx, old, .. } => buf[*idx] = old.clone(),
            Edit::Swap { a, b } => buf.swap(*a, *b),
        }
    }
}

fn parse_idx(s: &str) -> Option<usize> {
    if s.is_empty() || s.len() > 6 || !s.bytes().all(|b| b.is_ascii_digit()) {
        None
    } else {
        s.parse().ok()
    }
}

fn push_edit(undo: &mut VecDeque<Edit>, edit: Edit) {
    if undo.len() == UNDO_LIMIT {
        undo.pop_front();
    }
    undo.push_back(edit);
}

/// Executes one non-empty command line. Output is appended to `out`;
/// an error is returned as its message (without the `error: ` prefix).
fn exec(
    line: &str,
    buf: &mut Vec<String>,
    undo: &mut VecDeque<Edit>,
    redo: &mut Vec<Edit>,
    out: &mut String,
) -> Result<(), &'static str> {
    let fields: Vec<&str> = line.split(' ').collect();
    let n = fields.len();
    let edit = match fields[0] {
        "undo" => {
            if n != 1 {
                return Err("bad arguments");
            }
            let edit = undo.pop_back().ok_or("nothing to undo")?;
            edit.revert(buf);
            redo.push(edit);
            return Ok(());
        }
        "redo" => {
            if n != 1 {
                return Err("bad arguments");
            }
            let mut edit = redo.pop().ok_or("nothing to redo")?;
            edit.apply(buf);
            push_edit(undo, edit);
            return Ok(());
        }
        "print" => {
            if n != 1 {
                return Err("bad arguments");
            }
            if buf.is_empty() {
                out.push_str("(empty)\n");
            } else {
                for (i, text) in buf.iter().enumerate() {
                    out.push_str(&format!("{}: {}\n", i, text));
                }
            }
            return Ok(());
        }
        "delete" => {
            if n != 2 {
                return Err("bad arguments");
            }
            let idx = parse_idx(fields[1]).ok_or("bad arguments")?;
            if idx >= buf.len() {
                return Err("bad index");
            }
            Edit::Delete { idx, removed: String::new() }
        }
        "swap" => {
            if n != 3 {
                return Err("bad arguments");
            }
            let a = parse_idx(fields[1]).ok_or("bad arguments")?;
            let b = parse_idx(fields[2]).ok_or("bad arguments")?;
            if a >= buf.len() || b >= buf.len() {
                return Err("bad index");
            }
            Edit::Swap { a, b }
        }
        "insert" | "replace" => {
            let parts: Vec<&str> = line.splitn(3, ' ').collect();
            if parts.len() != 3 || parts[2].is_empty() {
                return Err("bad arguments");
            }
            let idx = parse_idx(parts[1]).ok_or("bad arguments")?;
            let text = parts[2].to_string();
            if fields[0] == "insert" {
                if idx > buf.len() {
                    return Err("bad index");
                }
                Edit::Insert { idx, text }
            } else {
                if idx >= buf.len() {
                    return Err("bad index");
                }
                Edit::Replace { idx, text, old: String::new() }
            }
        }
        _ => return Err("unknown command"),
    };

    let mut edit = edit;
    edit.apply(buf);
    push_edit(undo, edit);
    redo.clear();
    Ok(())
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut buf: Vec<String> = Vec::new();
    let mut undo: VecDeque<Edit> = VecDeque::new();
    let mut redo: Vec<Edit> = Vec::new();
    let mut out = String::new();
    let mut failed = false;

    for line in input.lines() {
        if line.is_empty() {
            continue;
        }
        if let Err(msg) = exec(line, &mut buf, &mut undo, &mut redo, &mut out) {
            out.push_str(&format!("error: {}\n", msg));
            failed = true;
        }
    }

    io::stdout().write_all(out.as_bytes()).unwrap();
    std::process::exit(if failed { 1 } else { 0 });
}
